pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound to a reasonable range to keep the test wide but fundable
        amount = bound(amount, 1, 100 ether);
        address actor = address(0x1234);
        vm.deal(actor, amount);
        vm.prank(actor);
        try c.go{value: amount}() {
        } catch {}
        // After go() completes (whether revert or success), check the invariant
        // The reference contract always transfers its balance to the owner, so balance must be zero after a call.
        // The mutant selfdestructs before transfer, leaving its balance behind.
        assertTrue(address(c).balance == 0);
    }
}

